INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar o nível da caixa de marcha.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'BUS', 109, TRUE);
