INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('AMORTECEDOR - Verificar aperto dos amortecedores, devem estar bem fixados, sem vazamentos de óleo, amassados, quebrados ou desgaste excessivo nas buchas.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 118, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar molas e sapatas (não devem apresentar trincas, soldas, folgas, deformações ou mesmo quebra, além de corretamente alinhadas e fixadas).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 119, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar balanças do feixe de molas (não devem apresentar trincas, soldas, folgas ou mesmo quebra, além de corretamente fixadas.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 120, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar pino de centro (o pino deve estar integro e conservado, bem fixado torqueado e posicionado.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 121, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar algemas do feixe de mola (devem estar integro e conservado, bem fixado torqueado e posicionado).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 122, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar batentes do feixe de mola (integridade, conservação e fixação).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 123, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar estado dos grampos (U) (devem estar torqueados corretamente, sem torção, trincas ou falta de porcas de fixação. Reapertar se necessário conforme a tabela de torque).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 124, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SUSPESÃO PNEUMÁTICA (SE APLICÁVEL) - Verificar vazamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 125, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar barra V (se aplicável) (devem estar bem fixadas e com as buchas em perfeito estado de conservação e integridade).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 126, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar barra estabilizadora (integridade) (não deve apresentar folga excessiva nas buchas, não devem estar empenadas e devidamente fixadas e com todos os parafuso.s de fixação torqueados corretamente).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 127, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar o estado de conservação e inegridade e fixação dos braços da barra estabilizadora.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 128, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ELEMENTO ESTRUTURAIS (BRAÇOS, SUPORTES E TENSORES) - Verificar fixação, integridade, conservação dos elementos estruturais.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 129, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ELEMENTOS DE ARTICULAÇÃO - Verificar fixação, integridade, conservação dos elementos de articulação.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 130, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ELEMENTOS LIMITADORES - Verificar fixação, integridade, conservação dos elementos limitadores.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 131, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ELEMENTOS DE REGULAGEM (EXCÊNTRICOS, CALÇOS, PARAFUSO.S REGULADORES) - Verificar fixação, integridade, conservação dos elementos de regulagem.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'BUS', 132, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - MANGA DE EIXO - Verificar folga das mangas de eixo, (levantar as rodas para verificação. Não deve apresentar folga superior ao recomendado pelo fabricante).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'BUS', 133, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - CUBO DE RODA - Verificar cubos de rodas, (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'BUS', 134, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - PONTA DO EIXO - Verificar ponta do eixo, (verificar pontas do eixo, integridade, conservação e fixação).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'BUS', 135, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - ROLAMENTOS - Verificar rolamento (os rolamentos devem ser lavados em bancada e inspecionados, não devem possuir folgas excessivas, escorias, desgastes ou algum tipo de avaria. Utilizar sempre a graxa e quantidade recomendada. Ajustar/trocar conforme manual técnico).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'BUS', 136, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - GRAXA - Trocar graxa do cubo de rodas (conforme orientação do fabricante).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'BUS', 137, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - CUBO DE RODA - Verificar cubos de rodas, (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 138, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - ROLAMENTOS - Verificar folga no rolamento, (os rolamentos devem ser lavados em bancada e inspecionados, não deve possuir folgas excessivas, escorias, desgastes ou algum tipo de avaria. Utilizar sempre a graxa e quantidade recomendada. Ajustar conforme manual técnico).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 139, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar eixo diferencial, (não deve apresentar qualquer vazamento de óleo).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 140, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar tampa, carcaça e retentor (devem estar íntegros, sem desgastes e sem apresentar vazamentos).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 141, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar nível de óleo do eixo diferencial, (óleo do diferencial deve estar nivelado com bujão de abastecimento).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 142, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar nível do óleo dos cubos de campana, (óleo dos cubos devem estar nivelado com bujão de abastecimento central).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 143, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar cubo campana e cubos de roda. (não devem apresentar qualquer vazamento, trincas e desgaste no centralizadores de roda).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 144, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar estado do respiro do diferencial; fixação, estado e entupimento (devem estar limpos bem fixados e desobstruídos não devem conter trincas e avarias).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 145, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - PONTA DO EIXO - Verificar ponta do eixo (verificar pontas do eixo, integridade, conservação e fixação do eixo).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 146, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - GRAXA - Trocar graxa do cubo de rodas (conforme orientação do fabricante).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 147, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - CUBO DE RODA - Verificar cubos de rodas (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'BUS', 148, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('NÍVEL DE ÓLEO HIDRÁULICO - Verifique o nível de óleo hidráulico (complete se necessário).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 149, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - RESERVATÓRIO - Verificar filtro do reservatório (o filtro deve ser trocado conforme recomendação do fabricante).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 150, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - RESERVATÓRIO - Verificar o reservatório hidráulico (estado de conservação, integridade, fixação e vazamentos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 151, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - ESTANQUEIDADE - Verificar estanqueidade do sistema de direção hidráulica', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 152, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - MANGUEIRAS E CONEXÕES - Verificar mangueiras e conexões (estado de conservação, integridade, fixação e vazamentos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 153, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA DE DIREÇÃO TRASVERSAL - BARRA LONGA - Verificar barra longa de direção (barra longa não deve apresentar empeno, soldas ou folga nas ponteiras esféricas. Realizar o esterçamento completo para ambos os lados, para verificar os ruídos, estalos do sistema de direção e atritos dos pneus com as partes móveis, verificar estado de conservação, integridade, fixação e vazamentos.', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 154, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA DE DIREÇÃO LOGITUDINAL - BARRA CURTA - Verificar barra curta de direção (barra curta não deve apresentar empeno, soldas ou folga nas ponteiras esféricas. Realizar o esterçamento completo para ambos os lados, para verificar os ruídos, estalos do sistema de direção e atritos dos pneus com as partes móveis, verificar estado de conservação, integridade, fixação e vazamentos.', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 155, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MECANISMO, BARRAS E BRAÇOS - Mecanismo, barras e braços não deve apresentar empeno, soldas ou folgas. Realizar o esterçamento completo para ambos os lados, para verificar os ruídos, estalos do sistema de direção e atritos dos pneus com as partes moveis, verificar estado de conservação, integridade, fixação e vazamentos.', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 156, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE DIREÇÃO - SETOR DE DIREÇÃO - Verifique a folga do setor/caixa de direção (não deve apresentar vazamentos de óleo, ruído anormal, parafuso.s sem fixação, trincados ou incompletos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 157, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TERMINAL DE DIREÇÃO - PONTEIRA - Verificar o estado e folga dos terminais de direção (estado de conservação, integridade, fixação. Devem estar bem fixadas integras e conservadas, não devem apresentar folga excessiva).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 158, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VOLANTE DE DIREÇÃO E COLUNA - Verificar volante e coluna (deve estar em bom estado conservação, integras sem folgas e bem fixadas, verificar alinhamento do volante com as rodas).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 159, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('AMORTECEDOR DE DIREÇÃO (SE EXISTENTE) - Verificar vazamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'BUS', 160, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LONAS - Devem estar integras conservadas, fixadas sem trincas, sem contaminação e com espessura mínima adequada. Se necessário realizar troca conforme indicador de troca da lona.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 161, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TAMBOR - Devem estar integros, conservados, fixados sem trincas e com espessura mínima adequada, sem contaminação. Se necessário realizar troca.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 162, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DISCOS E PASTILHAS - Os discos e as pastilhas de freios devem estar integros, conservados, fixados sem trincas e com espessura mínima adequada, sem contaminação. Se necessário realizar troca.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 163, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CATRACAS - Devem estar acionando corretamente, sem folgas e bem ajustadas.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 164, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('GUARNIÇÃO DO SISTEMA DE FREIOS - As sapatas, lonas, tambores, rebites, roldanas, molas, contrapinos e eixo “s” devem estar íntegros, conservados, fixados e sem contaminação por outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 165, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO EXPANSOR - EIXO "S" - Verificar integridade, estado de conservação, fixação, completo com todos os componentes e adequado para uso.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 166, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('PROTETORES DE RODAS TRASEIRAS – (ESPELHO DE RODA) - Verificar integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 167, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CUÍCAS - As cuícas, devem estar íntegras, conservadas, sem vazamentos, bem fixadas, completas com pinos e contrapinos, haste integra e perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 168, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CUÍCAS - Medir a pressão pneumática em cada cuíca com a utilização de manômetro adequado e calibrado. A pressão não pode estar inferior ao recomendado pelo fabricante.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 169, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('RESERVATÓRIOS DE AR - Devem estar bem fixados sem amassado ou trinca. Verificar o dreno do reservatório se há alguma obstrução.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 170, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('COMPRESSOR - Verificar funcionamento, pressão de ar deve carregar conforme instrução do fabricante.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 171, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA APU - O filtro e a válvula devem estar bem fixados e limpos sem nenhuma obstrução (testar a descarga do ar quando completar a pressão).', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 172, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA APU - Trocar filtro conforme recomendação do fabricante.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 173, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA PEDAL - A válvula deve estar íntegra, conservada, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 174, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA RELÊ - A válvula deve estar íntegra, conservada, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 175, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA/MANETE FRIEO DE MÃO - A válvula deve estar íntegra, conservada, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 176, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULAS EM GERAL - As válvulas em geral, manômetro devem estar íntegros, conservados, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 177, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TUBULAÇÕES E CONEXÕES - As conexões, tubulações, mangueiras, filtros, devem estar íntegros, conservados, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 178, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ABS - O sistema não deve apresentar falhas no painel.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 179, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ABS - Verificar os chicotes, sensores e módulos do abs.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 180, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULA MODULADORA DO ABS A válvula deve estar íntegra, conservada, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes. Realizar a limpeza para evitar acúmulo de sujeira e resíduos.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'BUS', 181, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LIMPADOR DE PARA-BRISA - Verificar limpador de para brisa (deve estar com as paletas em bom estado de conservação, íntegros, bem fixados e funcionando em todos os estágios).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 182, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LAVADOR DE PARA-BRISA - Verificar lavador de para brisa (o nível de água deve estar completo, regulado sem nenhuma obstrução no esguicho).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 183, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BUZINA - Verificar funcionamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 184, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BATERIA E CHAVE GERAL - Verificar bateria e chave geral (deve estar bem fixado, com os polos e cabos devidamente isolados e protegidos, integra, conservada. E chave geral deve estar bem fixada, integra e deverá testar o funcionamento).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 185, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('PAINEL DE INSTRUMENTOS - Verificar instrumentos do painel (deve estar em bom estado de conservação, funcionamento com todos os indicadores funcionando, sem avarias ou trincas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 186, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('FARÓIS PRINCIPAIS E AUXILIARES - Verificar faróis principais (deve apresentar funcionamento correto em todos os estágios deve estar com a lente limpa, sem ofuscamento, sem trincas, reguladas e bem fixadas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 187, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LANTERNAS DE SINALIZAÇÃO - Verificar lanternas de sinalização (as lanternas de direção, alertas, lanternas de freio, lanterna delimitadoras, lanternas laterais, luzes de posição, sirene de ré, luz de ré, luz de placa, faixas refletivas e refletores laterais. Deve estar funcionando corretamente e com a lente limpa sem ofuscamento, sem trincas e bem fixadas. E verificar o funcionamento das luzes internas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 188, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CHICOTE ELETRICO E CABOS - Verificar chicotes elétricos (devem estar bem fixados, isolados, íntegros, conservados e sem atrito com outras peças).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 189, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('COMPUTADOR DE BORDO - Verificar possíveis falhas no computador de bordo (não deve apresentar falhas ativas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 190, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VIDRO ELETRICO/MANUAL - Verificar funcionamento do vidro e retrovisor elétrico, se aplicável (conjunto de teclas/módulo de comando deve estar em boas condições de conservação além de funcionarem corretamente todos os comandos).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 191, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ALTERNADOR - Verificar alternador (verificar funcionamento através do medidor de tensão, verificar estado, integridade e fixação).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 192, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOTOR DE PARTIDA - Verificar motor de arranque (verificar funcionamento, verificar estado, integridade e fixação).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'BUS', 193, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CHASSI - Verificar chassi (não deve apresentar trincas, deve estar íntegro, bem conservados e sem torção).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'BUS', 194, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TRAVESSAS - Verificar travessas (devem estar bem fixados sem trincas, integro, bem conservado com parafuso.s de fixação torqueados adequadamente).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'BUS', 195, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TORQUE DOS PARAFUSO.S CHASSI/IMPLEMENTO - Verificar torque dos parafusos chassi/implemento (os parafuso.s de fixação com batentes e molas devem estar em bom estado de integridade, conservação e torqueados adequadamente).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'BUS', 196, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('FIXAÇÃO E ESTADO DOS EXTRATORES DE PEDRA - Verificar fixação e estado dos extratores de pedra (devem estar bem fixados e sem avarias, sem empeno quebra ou trinca). Se aplicável.', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'BUS', 197, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SUPORTES FIXADOS NO CHASSI - Verificar suportes fixados no chassi (devem estar bem fixados, íntegros, conservados e sem avarias).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'BUS', 198, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LAVAR E LIMPAR - Lavar internamente, externamente e chassi por baixo.', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 199, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DOCUMENTAÇÃO - Avaliar a documentação CRLV, validade e dados do veículo.', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 200, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DESCRIÇÃO DOS REPAROS REALIZADOS', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 201, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU ÓLEO MOTOR;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 202, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU FILTRO LUBRIFICANTE;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 203, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU FILTRO DE AR;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 204, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU FILTRO DIESEL;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 205, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU FILTRO RACOR;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 206, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TOCOU FILTRO ARLA;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 207, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU ÓLEO DIFERENCIAL;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 208, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU ÓLEO DE CAIXA;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 209, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TROCOU CRUZETA CARDAN;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 210, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ELIMINOU FOLGA CARDAN;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 211, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('HIGIENIZOU INTERNO E EXTERNO;', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 212, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LUBRIFICOU TODOS OS PONTOS DE LUBRIFICAÇÃO.', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'BUS', 213, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('Lubrificar Mecanismo das portas;', 'GRUPO I - LUBRIFICAÇÃO', 'PREVENTIVA', 'VAN', 1, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('PARA-CHOQUES - Verificar funcionamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 02 - EQUIPAMENTOS OBRIGATÓRIOS', 'PREVENTIVA', 'VAN', 2, TRUE);
