INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TANQUE DO ARLA - Verificar vazamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 08 – MOTOR/ARLA', 'PREVENTIVA', 'VAN', 85, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE ESCAPAMENTO E CATALISADOR - Verificar todo sistema de escape (tubos, silenciadores, ponteiras) quanto a estanqueidade, estado de conservação e integridade, fixação dos tubos, suportes e abraçadeiras.', 'GRUPO 09 – MOTOR – SISTEMA DE EXAUSTÃO/ESCAPE', 'PREVENTIVA', 'VAN', 86, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE ESCAPAMENTO E CATALISADOR - Verificar escapamento alterado, Ruído acima do limite.', 'GRUPO 09 – MOTOR – SISTEMA DE EXAUSTÃO/ESCAPE', 'PREVENTIVA', 'VAN', 87, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE ESCAPAMENTO E CATALISADOR - Verificar o fucionamento, estado de conservação e integridade da Sonda Lambda.', 'GRUPO 09 – MOTOR – SISTEMA DE EXAUSTÃO/ESCAPE', 'PREVENTIVA', 'VAN', 88, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EMBREAGEM - Verificar desgaste atraves da janela de inspeção, se necessário trocar os componentes de embreagem: platô, disco e cilindro.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 89, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EMBREAGEM - Trocar fluido da embreagem conforme recomendação do fabricante.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 90, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CARDAN - CINTAS - As cintas do eixo cardan devem estar bem fixadas, posicionadas no local correto e adequadas.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 91, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CARDAN, CRUZETAS, MANCAIS, LUVAS, GARFO E FLANGE - Verificar integridade, estado de conservação, fixação, folgas, completo com todos os componentes e adequada para uso.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 92, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CARDAN, CRUZETAS, MANCAIS, LUVAS, GARFO E FLANGE - Verificar a fixação e integridade de todos os parafusos.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 93, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar vazamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 94, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar o nível da caixa de marcha.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 95, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Trocar óleo da caixa de marcha conforme recomendação do fabricante.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 96, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar o estado de conservação e intergridade dos suportes e coxins de fixação da caixa de marcha.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 97, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar o estado de conservação e intergridade das conexões pneumáticas da caixa de marcha.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 98, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE MARCHA - Verificar o estado de conservação e intergridade do chicote elétrico da caixa e seus conectores.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 99, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ALAVANCA DE MARCHAS - Verificar estado de conservação e integridade da alavanca de marcha, vedação de borracha e nível de ruídos, coifas.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 100, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MANOPLA DA ALAVANCA DE MARCHAS - Verificar estado de conservação e integridade da manopla do cambio.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 101, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CHAVE SELETORAS PARA CAMBIO REDUZIDO - Verificar estado de conservação e integridade e funcionamento.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 102, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TESTE DINÂMICO TRANSMISSÃO - Realizar o teste dinâmico no veículo para avaliar o funcionamento da embreagem e alavanca de marcha em todas as posições.', 'GRUPO 10 – SISTEMA DE TRANSMISSÃO', 'PREVENTIVA', 'VAN', 103, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('AMORTECEDOR - Verificar aperto dos amortecedores, devem estar bem fixados, sem vazamentos de óleo, amassados, quebrados ou desgaste excessivo nas buchas.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 104, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar molas e sapatas (não devem apresentar trincas, soldas, folgas, deformações ou mesmo quebra, além de corretamente alinhadas e fixadas).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 105, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar balanças do feixe de molas (não devem apresentar trincas, soldas, folgas ou mesmo quebra, além de corretamente fixadas.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 106, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar pino de centro (o pino deve estar integro e conservado, bem fixado torqueado e posicionado.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 107, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar algemas do feixe de mola (devem estar integro e conservado, bem fixado torqueado e posicionado).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 108, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar batentes do feixe de mola (integridade, conservação e fixação).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 109, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOLAS - Verificar estado dos grampos (U) (devem estar torqueados corretamente, sem torção, trincas ou falta de porcas de fixação. Reapertar se necessário conforme a tabela de torque).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 110, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SUSPESÃO PNEUMÁTICA (SE APLICÁVEL) - Verificar vazamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 111, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar barra V (se aplicável) (devem estar bem fixadas e com as buchas em perfeito estado de conservação e integridade).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 112, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar barra estabilizadora (integridade) (não deve apresentar folga excessiva nas buchas, não devem estar empenadas e devidamente fixadas e com todos os parafuso.s de fixação torqueados corretamente).', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 113, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BARRA ESTABILIZADORA - Verificar o estado de conservação e inegridade e fixação dos braços da barra estabilizadora.', 'GRUPO 11 – SISTEMA DE SUSPENSÃO', 'PREVENTIVA', 'VAN', 114, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - MANGA DE EIXO - Verificar folga das mangas de eixo, (levantar as rodas para verificação. Não deve apresentar folga superior ao recomendado pelo fabricante).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'VAN', 115, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - CUBO DE RODA - Verificar cubos de rodas, (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'VAN', 116, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - PONTA DO EIXO - Verificar ponta do eixo, (verificar pontas do eixo, integridade, conservação e fixação).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'VAN', 117, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - ROLAMENTOS - Verificar rolamento (os rolamentos devem ser lavados em bancada e inspecionados, não devem possuir folgas excessivas, escorias, desgastes ou algum tipo de avaria. Utilizar sempre a graxa e quantidade recomendada. Ajustar/trocar conforme manual técnico).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'VAN', 118, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO DIANTEIRO - GRAXA - Trocar graxa do cubo de rodas (conforme orientação do fabricante).', 'GRUPO 12 – SISTEMA DE SUSPENSÃO – EIXO DIANTEIRO', 'PREVENTIVA', 'VAN', 119, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - CUBO DE RODA - Verificar cubos de rodas, (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 120, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - ROLAMENTOS - Verificar folga no rolamento, (os rolamentos devem ser lavados em bancada e inspecionados, não deve possuir folgas excessivas, escorias, desgastes ou algum tipo de avaria. Utilizar sempre a graxa e quantidade recomendada. Ajustar conforme manual técnico).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 121, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar eixo diferencial, (não deve apresentar qualquer vazamento de óleo).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 122, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar tampa, carcaça e retentor (devem estar íntegros, sem desgastes e sem apresentar vazamentos).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 123, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar nível de óleo do eixo diferencial, (óleo do diferencial deve estar nivelado com bujão de abastecimento).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 124, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar nível do óleo dos cubos de campana, (óleo dos cubos devem estar nivelado com bujão de abastecimento central).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 125, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar cubo campana e cubos de roda. (não devem apresentar qualquer vazamento, trincas e desgaste no centralizadores de roda).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 126, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - EIXO DIFERENCIAL - Verificar estado do respiro do diferencial; fixação, estado e entupimento (devem estar limpos bem fixados e desobstruídos não devem conter trincas e avarias).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 127, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - PONTA DO EIXO - Verificar ponta do eixo (verificar pontas do eixo, integridade, conservação e fixação do eixo).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 128, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - GRAXA - Trocar graxa do cubo de rodas (conforme orientação do fabricante).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 129, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('EIXO TRASEIRO - CUBO DE RODA - Verificar cubos de rodas (devem estar ajustados adequadamente sem folga excessiva, desgaste, avarias ou graxa contaminada).', 'GRUPO 13 – SISTEMA DE SUSPENSÃO – EIXO TRASEIRO', 'PREVENTIVA', 'VAN', 130, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('NÍVEL DE ÓLEO HIDRÁULICO - Verifique o nível de óleo hidráulico (complete se necessário).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 131, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - RESERVATÓRIO - Verificar filtro do reservatório (o filtro deve ser trocado conforme recomendação do fabricante).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 132, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - RESERVATÓRIO - Verificar o reservatório hidráulico (estado de conservação, integridade, fixação e vazamentos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 133, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - ESTANQUEIDADE - Verificar estanqueidade do sistema de direção hidráulica', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 134, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SISTEMA DE DIREÇÃO - MANGUEIRAS E CONEXÕES - Verificar mangueiras e conexões (estado de conservação, integridade, fixação e vazamentos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 135, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MECANISMO, BARRAS E BRAÇOS - Mecanismo, barras e braços não deve apresentar empeno, soldas ou folgas. Realizar o esterçamento completo para ambos os lados, para verificar os ruídos, estalos do sistema de direção e atritos dos pneus com as partes moveis, verificar estado de conservação, integridade, fixação e vazamentos.', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 136, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CAIXA DE DIREÇÃO - SETOR DE DIREÇÃO - Verifique a folga do setor/caixa de direção (não deve apresentar vazamentos de óleo, ruído anormal, parafuso.s sem fixação, trincados ou incompletos).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 137, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TERMINAL DE DIREÇÃO - PONTEIRA - Verificar o estado e folga dos terminais de direção (estado de conservação, integridade, fixação. Devem estar bem fixadas integras e conservadas, não devem apresentar folga excessiva).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 138, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VOLANTE DE DIREÇÃO E COLUNA - Verificar volante e coluna (deve estar em bom estado conservação, integras sem folgas e bem fixadas, verificar alinhamento do volante com as rodas).', 'GRUPO 14 – SISTEMA DE DIREÇÃO', 'PREVENTIVA', 'VAN', 139, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LONAS - Devem estar integras conservadas, fixadas sem trincas, sem contaminação e com espessura mínima adequada. Se necessário realizar troca conforme indicador de troca da lona.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 140, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TAMBOR - Devem estar integros, conservados, fixados sem trincas e com espessura mínima adequada, sem contaminação. Se necessário realizar troca.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 141, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DISCOS E PASTILHAS - Os discos e as pastilhas de freios devem estar integros, conservados, fixados sem trincas e com espessura mínima adequada, sem contaminação. Se necessário realizar troca.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 142, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('PROTETORES DE RODAS TRASEIRAS – (ESPELHO DE RODA) - Verificar integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 143, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VÁLVULAS EM GERAL - As válvulas em geral, manômetro devem estar íntegros, conservados, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 144, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TUBULAÇÕES E CONEXÕES - As conexões, tubulações, mangueiras, filtros, devem estar íntegros, conservados, sem vazamentos, perfeito funcionamento e sem atrito com outros componentes.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 145, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ABS - O sistema não deve apresentar falhas no painel.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 146, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ABS - Verificar os chicotes, sensores e módulos do abs.', 'GRUPO 15 – SISTEMA DE FREIOS', 'PREVENTIVA', 'VAN', 147, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LIMPADOR DE PARA-BRISA - Verificar limpador de para brisa (deve estar com as paletas em bom estado de conservação, íntegros, bem fixados e funcionando em todos os estágios).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 148, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LAVADOR DE PARA-BRISA - Verificar lavador de para brisa (o nível de água deve estar completo, regulado sem nenhuma obstrução no esguicho).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 149, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BUZINA - Verificar funcionamento, integridade, estado de conservação, fixação, completo com todos os componentes e adequada para uso.', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 150, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('BATERIA E CHAVE GERAL - Verificar bateria e chave geral (deve estar bem fixado, com os polos e cabos devidamente isolados e protegidos, integra, conservada. E chave geral deve estar bem fixada, integra e deverá testar o funcionamento).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 151, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('PAINEL DE INSTRUMENTOS - Verificar instrumentos do painel (deve estar em bom estado de conservação, funcionamento com todos os indicadores funcionando, sem avarias ou trincas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 152, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('FARÓIS PRINCIPAIS E AUXILIARES - Verificar faróis principais (deve apresentar funcionamento correto em todos os estágios deve estar com a lente limpa, sem ofuscamento, sem trincas, reguladas e bem fixadas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 153, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LANTERNAS DE SINALIZAÇÃO - Verificar lanternas de sinalização (as lanternas de direção, alertas, lanternas de freio, lanterna delimitadoras, lanternas laterais, luzes de posição, sirene de ré, luz de ré, luz de placa, faixas refletivas e refletores laterais. Deve estar funcionando corretamente e com a lente limpa sem ofuscamento, sem trincas e bem fixadas. E verificar o funcionamento das luzes internas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 154, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CHICOTE ELETRICO E CABOS - Verificar chicotes elétricos (devem estar bem fixados, isolados, íntegros, conservados e sem atrito com outras peças).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 155, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('COMPUTADOR DE BORDO - Verificar possíveis falhas no computador de bordo (não deve apresentar falhas ativas).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 156, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('VIDRO ELETRICO/MANUAL - Verificar funcionamento do vidro e retrovisor elétrico, se aplicável (conjunto de teclas/módulo de comando deve estar em boas condições de conservação além de funcionarem corretamente todos os comandos).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 157, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('ALTERNADOR - Verificar alternador (verificar funcionamento através do medidor de tensão, verificar estado, integridade e fixação).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 158, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('MOTOR DE PARTIDA - Verificar motor de arranque (verificar funcionamento, verificar estado, integridade e fixação).', 'GRUPO 16 – SISTEMA ELÉTRICO EM GERAL', 'PREVENTIVA', 'VAN', 159, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('CHASSI - Verificar chassi (não deve apresentar trincas, deve estar íntegro, bem conservados e sem torção).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'VAN', 160, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('TRAVESSAS - Verificar travessas (devem estar bem fixados sem trincas, integro, bem conservado com parafuso.s de fixação torqueados adequadamente).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'VAN', 161, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('SUPORTES FIXADOS NO CHASSI - Verificar suportes fixados no chassi (devem estar bem fixados, íntegros, conservados e sem avarias).', 'GRUPO 17 – CHASSI', 'PREVENTIVA', 'VAN', 162, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('LAVAR E LIMPAR - Lavar internamente, externamente e chassi por baixo.', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'VAN', 163, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DOCUMENTAÇÃO - Avaliar a documentação CRLV, validade e dados do veículo.', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'VAN', 164, TRUE);
INSERT INTO checklist_itens (descricao, categoria, tipo_manutencao, vehicle_type_applicable, ordem, ativo) VALUES ('DESCRIÇÃO DOS REPAROS REALIZADOS', 'GRUPO 18 – GERAL', 'PREVENTIVA', 'VAN', 165, TRUE);